import unittest
from app.totals import total

class TestTotal(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(total([]), 0)

    def test_positive(self):
        self.assertEqual(total([1, 2, 3]), 6)

    def test_negative_and_zero(self):
        self.assertEqual(total([-3, 0, 2]), -1)
